#!/usr/bin/env bash
# scripts/lib/discover-exec-by-path-scripts.sh
#
# Enumerates every scripts/*.sh|*.py that a systemd unit (ExecStart=/
# ExecStartPre=) or an /etc/cron.d/* entry (the units are generated by
# scripts/install-aux-units.sh, the cron entries by it and by every
# scripts/*/install-cron.sh it executes) execs DIRECTLY BY PATH — i.e. execve()'d
# with no interpreter in front of it, so it needs the git index mode
# 100755 (+x) to survive an rsync deploy/rollback (rsync/tar preserve the
# git-recorded mode; a 100644 script exec'd by path fails 203/EXEC).
#
# A script passed as an ARGUMENT to an interpreter (`python3 foo.py`,
# `bash foo.sh`) does NOT need +x — the interpreter opens it for reading,
# never execve()s it — so those are deliberately excluded here.
#
# WHY THIS EXISTS: hydra-daily-audit.service failed 203/EXEC at
# 2026-09-22 08:00Z because rollback.sh rsynced the repo over /opt/hydra
# without repairing exec bits, and scripts/hydra-daily-audit.py was
# committed 100644 (deploy.sh:2318's `chmod +x` normally papers over
# this on the forward path; rollback.sh had no equivalent line). See
# scripts/tests/exec-bits-guard.bats, which uses this function to assert
# every discovered target is 100755 in the git index.
#
# Sourced by the bats guard AND safe to run standalone for a manual audit:
#   scripts/lib/discover-exec-by-path-scripts.sh
set -uo pipefail

discover_exec_by_path_scripts() {
  local repo_root="$1"
  local installer="$repo_root/scripts/install-aux-units.sh"
  local found=()

  is_interpreter() {
    case "$1" in
      /usr/bin/python3|/usr/bin/bash|python3|bash|sh|/bin/bash|/bin/sh) return 0 ;;
      *) return 1 ;;
    esac
  }

  # `env` is a LAUNCHER, not an interpreter: `/usr/bin/env foo` execve()s
  # `foo` directly (after resolving it on PATH and applying any leading
  # NAME=VALUE assignments/options), it does not open `foo` for reading the
  # way python3/bash do. Handled separately below so the real command env
  # hands off to gets classified on its own merits (QA round-2 finding:
  # treating `/usr/bin/env` like an interpreter made the gate fail OPEN for
  # `ExecStart=/usr/bin/env MODE=prod $HYDRA_ROOT/scripts/foo.sh`).
  is_env_launcher() {
    case "$1" in
      /usr/bin/env|/bin/env) return 0 ;;
      *) return 1 ;;
    esac
  }

  # One normalization for every site that turns a token into a repo path:
  # strip shell quoting and a trailing `;`, then the $HYDRA_ROOT/${HYDRA_ROOT}
  # or /opt/hydra prefix. A quoted target (`exec "$HYDRA_ROOT/scripts/x.sh"`)
  # is the same by-path exec as an unquoted one.
  normalize_token() {
    local t="$1"
    local prev=""
    while [ "$t" != "$prev" ]; do
      prev="$t"
      t="${t%;}"; t="${t#[\"\']}"; t="${t%[\"\']}"
    done
    t="${t/\$\{HYDRA_ROOT\}\//}"
    t="${t/\$HYDRA_ROOT\//}"
    t="${t#/opt/hydra/}"
    printf '%s' "$t"
  }

  # systemd allows several commands in one ExecStart= (Type=oneshot),
  # separated by a standalone `;`. Emit one `ExecStart=<command>` line per
  # command so each is classified on its own. Quote-aware, so the `;` in
  # `bash -lc 'a; exec b'` stays inside its command; `\;` is a literal arg.
  # Runs of spaces/tabs collapse to one space, so every later split on " "
  # sees systemd's own tokenization (a tab after the target is valid).
  split_exec_commands() {
    awk '{
      pos = index($0, "ExecStartPre="); key = "ExecStartPre="
      if (pos == 0) { pos = index($0, "ExecStart="); key = "ExecStart=" }
      if (pos == 0) next
      head = substr($0, 1, pos - 1) key
      body = substr($0, pos + length(key))
      n = length(body); seg = ""; q = ""
      for (i = 1; i <= n; i++) {
        c = substr(body, i, 1)
        if (c == "\\" && q != "'"'"'") { seg = seg c substr(body, i + 1, 1); i++; continue }
        if (q == "") {
          if (c == "\"" || c == "'"'"'") q = c
          else if (c == ";" && (i == 1 || substr(body, i - 1, 1) ~ /[ \t]/) && (i == n || substr(body, i + 1, 1) ~ /[ \t]/)) {
            gsub(/[ \t]+/, " ", seg); sub(/^ /, "", seg); sub(/ $/, "", seg)
            if (seg != "") print head seg
            seg = ""; continue
          }
        } else if (c == q) q = ""
        seg = seg c
      }
      gsub(/[ \t]+/, " ", seg); sub(/^ /, "", seg); sub(/ $/, "", seg)
      if (seg != "") print head seg
    }'
  }

  # 1) systemd ExecStart=/ExecStartPre= lines: the standalone unit template
  #    (scripts/aux-units/*.service, *.path) plus every heredoc unit the
  #    installer writes.
  local unit_sources=()
  local f
  for f in "$repo_root"/scripts/aux-units/*.service "$repo_root"/scripts/aux-units/*.path; do
    [ -f "$f" ] && unit_sources+=("$f")
  done
  [ -f "$installer" ] && unit_sources+=("$installer")

  local line rest first norm exec_target
  local env_toks env_idx env_tok env_real_idx env_skip_next
  local unsupported=0
  if [ "${#unit_sources[@]}" -gt 0 ]; then
    # Grab the FULL ExecStart=/ExecStartPre= line (not just the first two
    # tokens) -- an interpreter-prefixed unit like
    #   ExecStart=/usr/bin/bash -lc 'set -a; . env; exec $HYDRA_ROOT/scripts/foo.sh'
    # hides its real target past token 2, inside a quoted sub-command.
    while IFS= read -r line; do
      rest="${line#*ExecStart=}"
      [ "$rest" = "$line" ] && rest="${line#*ExecStartPre=}"
      first="${rest%% *}"
      # systemd executable prefixes (-, @, :, +, !, !!) precede the path in
      # the same token; they change failure/privilege/argv0 handling, never
      # which file is exec'd. `@` makes the NEXT token argv[0], which the
      # direct-target check below ignores anyway.
      while [[ "$first" == [-@:+!]* ]]; do first="${first:1}"; done
      if [ -z "$first" ]; then
        echo "discover-exec-by-path-scripts: unsupported ExecStart form in: $line" >&2
        unsupported=1; continue
      fi
      rest="$first${rest#"${rest%% *}"}"

      if is_env_launcher "$first"; then
        # Skip env's own options (-i, -S, ...) and any leading NAME=VALUE
        # assignments to find the command env actually execve()s, then
        # classify THAT token -- as a direct target below, or by falling
        # into the interpreter branch if env's own target is itself an
        # interpreter (`/usr/bin/env bash foo.sh` reads foo.sh, same as
        # plain `bash foo.sh`).
        # -C/--chdir and -u/--unset take their operand as the NEXT token, so
        # skip it too. -S/--split-string re-tokenizes a string we cannot
        # follow here, so it fails closed instead of guessing a command.
        env_toks=()
        read -ra env_toks <<< "${rest#* }"
        env_real_idx=-1
        env_skip_next=0
        for env_idx in "${!env_toks[@]}"; do
          env_tok="${env_toks[$env_idx]}"
          if [ "$env_skip_next" = 1 ]; then env_skip_next=0; continue; fi
          case "$env_tok" in
            -C|-u|--chdir|--unset) env_skip_next=1; continue ;;
            -S*|--split-string*)
              echo "discover-exec-by-path-scripts: unsupported env form '$env_tok' in: $line" >&2
              unsupported=1; break ;;
            -*) continue ;;
            [A-Za-z_]*=*) continue ;;
            *) env_real_idx="$env_idx"; break ;;
          esac
        done
        if [ "$env_real_idx" -ge 0 ]; then
          first="${env_toks[$env_real_idx]}"
          rest="$(IFS=' '; echo "${env_toks[*]:$env_real_idx}")"
        else
          first=""
        fi
      fi

      if is_interpreter "$first"; then
        # A bare `exec <path>` inside the interpreter's command string
        # replaces that shell process with <path> via execve() -- the
        # same by-path exec as a plain ExecStart= target -- so it needs
        # +x too, even though the outer ExecStart= is interpreter-led.
        # (install-aux-units.sh:2452, refresh-dedupe-cache.sh.)
        # `exec -a NAME path` and similar take options we don't parse, so
        # an option-led exec fails closed rather than being skipped.
        while IFS= read -r exec_target; do
          [ -n "$exec_target" ] || continue
          case "$exec_target" in
            -*)
              echo "discover-exec-by-path-scripts: unsupported exec form '$exec_target' in: $line" >&2
              unsupported=1; continue ;;
          esac
          norm="$(normalize_token "$exec_target")"
          # `exec env … foo.sh` / `exec bash foo.sh` hand off again; what
          # finally runs is not this token, so fail closed, don't guess.
          if is_env_launcher "$norm" || is_interpreter "$norm"; then
            echo "discover-exec-by-path-scripts: unsupported nested launcher after exec ('$exec_target') in: $line" >&2
            unsupported=1; continue
          fi
          case "$norm" in
            scripts/*.sh|scripts/*.py) found+=("$norm") ;;
          esac
        done < <(grep -oE '(^|[^[:alnum:]_])exec[[:space:]]+[^[:space:]]+' <<< "$rest" \
                    | awk '{print $NF}')
        continue
      fi
      norm="$(normalize_token "$first")"
      case "$norm" in
        scripts/*.sh|scripts/*.py) found+=("$norm") ;;
      esac
    done < <(grep -rhE 'ExecStart(Pre)?=' \
                "${unit_sources[@]}" 2>/dev/null | split_exec_commands || true)
  fi

  # 2) /etc/cron.d/* heredoc lines inside the cron WRITERS: install-aux-units.sh
  #    plus any scripts/*/install-cron.sh (the churn signal's writer is its own
  #    file so the suite can execute it against a temp root - firstmate
  #    2026-11-04 - and its cron targets are just as direct-exec as the
  #    installer's). A standard 5-field cron schedule + "root" + optional
  #    VAR=val/flock wrapper + the command; none are interpreter-prefixed
  #    today, so any scripts/*.sh|py token not immediately preceded by a known
  #    interpreter token is direct-exec.
  local cron_sources=()
  [ -f "$installer" ] && cron_sources+=("$installer")
  local writer
  for writer in "$repo_root"/scripts/*/install-cron.sh; do
    [ -f "$writer" ] && cron_sources+=("$writer")
  done
  if [ "${#cron_sources[@]}" -gt 0 ]; then
    local toks tok prev
    while IFS= read -r line; do
      line="$(tr -s ' \t' ' ' <<< "$line")"
      [[ "$line" =~ ^[^[:space:]]+\ [^[:space:]]+\ [^[:space:]]+\ [^[:space:]]+\ [^[:space:]]+\ root\  ]] || continue
      read -ra toks <<< "$line"
      prev=""
      for tok in "${toks[@]}"; do
        norm="$(normalize_token "$tok")"
        case "$norm" in
          scripts/*.sh|scripts/*.py)
            is_interpreter "$prev" || found+=("$norm")
            ;;
        esac
        prev="$tok"
      done
    done < <(grep -hoE '^[^[:space:]]+[[:blank:]]+[^[:space:]]+[[:blank:]]+[^[:space:]]+[[:blank:]]+[^[:space:]]+[[:blank:]]+[^[:space:]]+[[:blank:]]+root[[:blank:]].*$' \
                "${cron_sources[@]}" 2>/dev/null || true)
  fi

  if [ "${#found[@]}" -gt 0 ]; then
    printf '%s\n' "${found[@]}" | sort -u
  fi
  [ "$unsupported" = 0 ]
}

# Allow standalone execution for a manual audit, without affecting a `source`.
if [ "${BASH_SOURCE[0]}" = "${0}" ]; then
  discover_exec_by_path_scripts "$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
fi
